fn hero_tree() -> T {
    T::Object(vec![
        ("generic_data_type", T::Str("CitadelHeroData_t".into())),
        (
            "hero_base",
            T::Object(vec![("m_HeroID", T::Int(0))]),
        ),
        (
            "hero_test",
            T::Object(vec![
                ("m_HeroID", T::Int(7)),
                ("m_bDisabled", T::Bool(false)),
                (
                    "m_eHeroDevelopmentState",
                    T::Str("EHeroDevState_Release".into()),
                ),
                (
                    "m_strMinimapImage",
                    T::Str("file://{images}/heroes/test_mm.psd".into()),
                ),
                (
                    "m_strTopBarVertical",
                    T::Str("file://{images}/heroes/test_vertical.psd".into()),
                ),
                (
                    "m_strIconHeroCard",
                    T::Str("file://{images}/heroes/test_card.psd".into()),
                ),
            ]),
        ),
    ])
}

