#[test]
fn extract_writes_pack_and_blobs() {
    let fixture = build_fixture(
        &extraction_entries(),
        &[FixtureEntry::new(
            ENTITIES,
            kv3_resource(&encode_kv3(&entity_tree(), 0)),
        )],
    );
    let out = tempfile::tempdir().expect("out dir");

    let report = extract(&fixture.game, out.path()).expect("extract");
    assert_eq!(report.files.len(), 12);
    assert_eq!(report.blobs, 11);
    assert_eq!(report.sources, 12);

    for file in [
        "map/minimap_midtown_mid.png",
        "map/minimap_midtown_mid_tunnels.png",
        "map/minimap_midtown_rat_tunnels.png",
        "heroes/7.png",
        "topbar/heroes/7.png",
        "topbar/heroes/7_card.png",
        "topbar/hero_image_mask_psd.png",
        "topbar/icon_ultimate.svg",
        "hud/hero_badge.vcss",
        "icons/base/minimap_midtown_mid_psd.png",
        "icons/base/minimap_midtown_mid_tunnels_psd.png",
        "icons/base/minimap_midtown_rat_tunnels_psd.png",
    ] {
        assert!(out.path().join(file).is_file(), "missing {file}");
    }

    let pack: serde_json::Value =
        serde_json::from_slice(&std::fs::read(out.path().join("pack.json")).expect("read pack"))
            .expect("parse pack");
    assert_eq!(pack["schema"].as_u64(), Some(3));
    assert_eq!(pack["extractor"]["name"].as_str(), Some("mapcro-extract"));
    assert_eq!(pack["game"]["client_version"].as_u64(), Some(1234));
    assert_eq!(pack["game"]["source_revision"].as_u64(), Some(5678));
    assert_eq!(pack["game"]["date"].as_str(), Some("Jan 02 2030"));
    assert_eq!(pack["sources"].as_array().expect("sources").len(), 12);
    assert_eq!(pack["blobs"].as_object().expect("blobs").len(), 11);

    let heroes = pack["heroes"].as_array().expect("heroes");
    assert_eq!(heroes.len(), 1);
    assert_eq!(heroes[0]["hero_id"].as_u64(), Some(7));
    assert_eq!(heroes[0]["class_name"].as_str(), Some("hero_test"));
    assert_eq!(heroes[0]["name"].as_str(), Some("Test Hero"));
    assert_eq!(heroes[0]["dev_state"].as_str(), Some("EHeroDevState_Release"));
    assert_eq!(heroes[0]["disabled"].as_bool(), Some(false));
    assert_eq!(heroes[0]["minimap_blob"].as_str(), Some("heroes/7"));
    assert_eq!(heroes[0]["topbar_blob"].as_str(), Some("topbar/heroes/7"));
    assert_eq!(heroes[0]["card_blob"].as_str(), Some("topbar/heroes/7_card"));

    let entities = pack["entities"].as_array().expect("entities");
    assert_eq!(entities.len(), 9);
    let by = |key: &str| entities.iter().find(|e| e["key"] == key).unwrap_or_else(|| panic!("no {key}"));
    assert_eq!(by("patron:amber:lane1:1")["kind"].as_str(), Some("patron"));
    // The Soul Urn's delivery point, a neutral site on the nearest lane.
    assert_eq!(by("urn:neutral:lane1:1")["world"][0].as_f64(), Some(-6592.0));
    // Camps carry their tier where the map gives one, and nothing otherwise.
    let camps: Vec<(&str, Option<&str>)> =
        entities.iter().filter(|e| e["kind"] == "camp").map(|e| (e["src"]["targetname"].as_str().unwrap_or(""), e["tier"].as_str())).collect();
    assert_eq!(camps.len(), 2);
    assert!(camps.contains(&("[PR#]1380394_chinatown_bell_1", Some("vaults"))), "{camps:?}");
    assert!(camps.contains(&("[PR#]plain_camp", None)), "{camps:?}");
    assert!(by("urn:neutral:lane1:1").get("tier").is_none(), "only camps carry a tier");
    // The lane shop, not the base's; the teleporter with where it lets out; the healing pickup
    // and not the other spawner; the tough crate and not the wooden one.
    let furniture: Vec<(&str, &str)> = entities
        .iter()
        .filter(|e| ["shop", "teleporter", "heal", "tough_crate"].contains(&e["kind"].as_str().unwrap_or("")))
        .map(|e| (e["kind"].as_str().unwrap_or(""), e["src"]["hammeruniqueid"].as_str().unwrap_or("")))
        .collect();
    assert_eq!(furniture, [("heal", "h1"), ("shop", "s1"), ("teleporter", "t1"), ("tough_crate", "c1")]);
    let shop = entities.iter().find(|e| e["kind"] == "shop").expect("shop");
    assert_eq!(shop["team"].as_str(), Some("amber"));
    let tele = entities.iter().find(|e| e["kind"] == "teleporter").expect("teleporter");
    assert_eq!(tele["exit"], serde_json::json!([3904.0, -1664.0, -144.0]));
    assert!(shop.get("exit").is_none(), "only teleporters carry an exit");
    assert_eq!(
        by("zipline:neutral:lane1:1")["nodes"].as_array().expect("nodes").len(),
        1,
        "zipline node was not joined"
    );
    assert_eq!(
        pack["geometry_hash"].as_str().expect("geometry_hash").len(),
        64
    );

    assert_eq!(pack["icons"].as_array().expect("icons").len(), 3);
    assert_eq!(
        pack["icons_skipped"].as_array().expect("icons_skipped").len(),
        0
    );
    assert_eq!(
        pack["hud_sources"].as_array().expect("hud_sources").len(),
        1
    );
    assert_eq!(
        pack["hud_sources"][0]["key"].as_str(),
        Some("hud/hero_badge.vcss")
    );
}

/// Local-only check against a real install. Run with:
/// `MAPCRO_GAME_DIR=~/.local/share/Steam/steamapps/common/Deadlock/game/citadel \
///  nix develop -c cargo test -p mapcro-extract --test extract -- --ignored real_install`
#[test]
#[ignore = "reads the local Deadlock install; set MAPCRO_GAME_DIR to run"]
fn real_install() {
    let Some(game) = std::env::var_os("MAPCRO_GAME_DIR") else {
        eprintln!("MAPCRO_GAME_DIR is not set; skipping real-install test");
        return;
    };

    let out = Path::new("/tmp/mapcro-extract2-real");
    let _ = std::fs::remove_dir_all(out);
    let report = extract(Path::new(&game), out).expect("real extraction");

    assert!(out.join("map/minimap_midtown_mid.png").is_file());
    assert!(out.join("map/minimap_midtown_mid_tunnels.png").is_file());
    assert!(out.join("map/minimap_midtown_rat_tunnels.png").is_file());
    assert!(out.join("pack.json").is_file());

    let pack: serde_json::Value =
        serde_json::from_slice(&std::fs::read(out.join("pack.json")).expect("read pack"))
            .expect("parse pack");
    assert!(pack["heroes"].as_array().expect("heroes").len() > 40);
    assert!(pack["entities"].as_array().expect("entities").len() > 100);
    let powerups: Vec<&serde_json::Value> =
        pack["entities"].as_array().expect("entities").iter().filter(|e| e["kind"] == "powerup").collect();
    assert_eq!(powerups.len(), 2, "two mirrored powerup spawners");
    let urns: Vec<&str> =
        pack["entities"].as_array().expect("entities").iter().filter(|e| e["kind"] == "urn").filter_map(|e| e["key"].as_str()).collect();
    assert_eq!(urns, ["urn:neutral:lane1:1", "urn:neutral:lane6:1"], "the Soul Urn's two delivery points, west and east");
    // Every camp carries the game's tier (docs/research/map-objectives-audit.md): 51 camps and
    // the mid boss's own, with all 11 Sinner's Sacrifice camps as vaults whatever their names.
    let mut tiers = std::collections::BTreeMap::new();
    let mut vaults = Vec::new();
    for e in pack["entities"].as_array().expect("entities").iter().filter(|e| e["kind"] == "camp") {
        let tier = e["tier"].as_str().expect("every camp has a tier");
        *tiers.entry(tier).or_insert(0) += 1;
        if tier == "vaults" {
            vaults.push(e["src"]["targetname"].as_str().unwrap_or("").trim_start_matches("[PR#]"));
        }
    }
    assert_eq!(tiers, [("medium", 24), ("midboss", 1), ("strong", 12), ("vaults", 11), ("weak", 4)].into_iter().collect());
    for name in ["1380394_chinatown_bell_1", "theater_balcony_camp", "slums_garage_up_camp", "drug_store_camp", "hotel_01_camp"] {
        assert!(vaults.contains(&name), "{name} is a Sinner's Sacrifice camp: {vaults:?}");
    }
    // Map furniture (docs/research/map-objectives-audit.md): 8 shops (3 lane shops a team and the
    // 2 secret shops; the base's own isn't drawn), 4 teleporters in 2 two-way pairs, each letting
    // out beside the other end, 36 healing pickups and 78 tough crates.
    let of = |kind: &str| -> Vec<&serde_json::Value> { pack["entities"].as_array().expect("entities").iter().filter(|e| e["kind"] == kind).collect() };
    let mut shops = std::collections::BTreeMap::new();
    for e in of("shop") {
        *shops.entry(e["team"].as_str().expect("team")).or_insert(0) += 1;
    }
    assert_eq!(shops, [("amber", 3), ("neutral", 2), ("sapphire", 3)].into_iter().collect());
    let teleporters = of("teleporter");
    assert_eq!(teleporters.len(), 4);
    let xy = |v: &serde_json::Value| (v[0].as_f64().expect("x"), v[1].as_f64().expect("y"));
    for t in &teleporters {
        let (ex, ey) = xy(&t["exit"]);
        let other: Vec<&&serde_json::Value> = teleporters.iter().filter(|o| { let (x, y) = xy(&o["world"]); (x - ex).hypot(y - ey) < 200.0 }).collect();
        assert_eq!(other.len(), 1, "{} lets out beside exactly one other end", t["key"]);
        assert_ne!(other[0]["key"], t["key"], "a teleporter doesn't let out at itself");
        let (bx, by) = xy(&other[0]["exit"]);
        let (x, y) = xy(&t["world"]);
        assert!((bx - x).hypot(by - y) < 200.0, "{}'s pair leads back to it", t["key"]);
    }
    assert_eq!(of("heal").len(), 36);
    // The 78 tough crates; not the 423 wooden crates, 168 item containers or 3 bells.
    assert_eq!(of("tough_crate").len(), 78);
    assert!(pack["icons"].as_array().expect("icons").len() > 50);
    assert_eq!(pack["hud_sources"].as_array().expect("hud").len(), 11);
    let critical = pack["heroes"]
        .as_array()
        .expect("heroes")
        .iter()
        .filter(|h| h["critical_blob"].is_string())
        .count();
    assert!(critical > 30, "the low-health hero cards (m_strIconHeroCardCritical)");
    let cards: Vec<&serde_json::Value> =
        pack["heroes"].as_array().expect("heroes").iter().filter(|h| h["card_blob"].is_string()).collect();
    assert!(cards.len() > 30, "the hero cards (m_strIconHeroCard)");
    for h in &cards {
        let key = h["card_blob"].as_str().expect("card key");
        assert_eq!(key, format!("topbar/heroes/{}_card", h["hero_id"]));
        let blob = &pack["blobs"][key];
        // 280x380 (the mask's size) for most; a few are 240x320. Either way a portrait card.
        let (w, h) = (blob["w"].as_f64().expect("w"), blob["h"].as_f64().expect("h"));
        assert!(w >= 240.0 && (1.3..1.4).contains(&(h / w)), "{key}: {w}x{h} is not a hero card");
    }

    let topbar_blobs = pack["heroes"]
        .as_array()
        .expect("heroes")
        .iter()
        .filter(|hero| hero["topbar_blob"].is_string())
        .count();
    assert_eq!(topbar_blobs, 44, "expected 44 hero top-bar portraits");

    let fixed_topbar = pack["blobs"]
        .as_object()
        .expect("blobs")
        .keys()
        .filter(|key| key.starts_with("topbar/") && !key.starts_with("topbar/heroes/"))
        .count();
    assert_eq!(fixed_topbar, 15, "expected 15 fixed top-bar images");

    eprintln!(
        "real install: {} files, {} sources, {} blobs, pack at {}",
        report.files.len(),
        report.sources,
        report.blobs,
        report.pack.display()
    );
}
